${pagingTop}
SELECT
	homepage_id, event_idx, event_type, event_name, event_year, event_month, book_name, book_author, book_publisher,
	call_no, book_desc, event_start_date, event_end_date, book_image,
	top_html, bottom_html, delete_yn, add_date, add_id, modify_date, modify_id, applicant_id_yn, address_yn,
	(SELECT COUNT(*) FROM event_REQ WHERE homepage_id = a.homepage_id AND event_idx = a.event_idx) AS event_req_count,
	select_cnt, re_select_cnt
FROM
	EVENT a
WHERE
	homepage_id = #{homepage_id}
AND	delete_yn = 'N'

AND	${search_type} LIKE '%'||#{search_text}||'%'


AND	event_type = #{event_type}


AND	event_year = #{event_year}


AND event_month = #{event_month}

ORDER BY event_idx DESC
